package main

import (
	"encoding/csv"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// The matching CSV is generated by tools/build_statewide_station_matches.py.
// Paths are relative to server/ (the directory for `go run ./main`).
const conditionMatchesPath = "tools/statewide_station_matches.csv"
const conditionFeedTTL = 20 * time.Minute
const conditionWindow = 48 * time.Hour

var conditionParameters = map[string]string{
	"00010": "Water temperature",
	"00300": "Dissolved oxygen",
	"63680": "Turbidity",
	"00076": "Turbidity",
}

type conditionStation struct {
	ID        string  `json:"id"`
	Name      string  `json:"name"`
	Longitude float64 `json:"longitude"`
	Latitude  float64 `json:"latitude"`
	SegmentID string  `json:"segmentId,omitempty"`
}

type conditionReading struct {
	StationID      string    `json:"stationId"`
	StationName    string    `json:"stationName"`
	ParameterCode  string    `json:"parameterCode"`
	Parameter      string    `json:"parameter"`
	Value          float64   `json:"value"`
	Unit           string    `json:"unit"`
	Time           time.Time `json:"time"`
	ApprovalStatus string    `json:"approvalStatus,omitempty"`
	SeriesID       string    `json:"seriesId,omitempty"`
	Longitude      float64   `json:"longitude"`
	Latitude       float64   `json:"latitude"`
}

type conditionsResult struct {
	WaterbodyID            string             `json:"waterbodyId"`
	AsOf                   time.Time          `json:"asOf"`
	WindowHours            int                `json:"windowHours"`
	StationCount           int                `json:"stationCount"`
	ReadingCount           int                `json:"readingCount"`
	Stations               []conditionStation `json:"stations"`
	Readings               []conditionReading `json:"readings"`
	HistoricalReadings     []conditionReading `json:"historicalReadings"`
	HistoricalStationCount int                `json:"historicalStationCount"`
	Note                   string             `json:"note"`
}

type cachedConditionObservation struct {
	StationID      string
	ParameterCode  string
	Value          float64
	Unit           string
	Time           time.Time
	ApprovalStatus string
	SeriesID       string
}

// Cache one statewide feed, rather than one expensive USGS fetch per waterbody.
// Holding the mutex during a refresh prevents simultaneous duplicate downloads.
// The response is constructed from cached measurements on EVERY request so the
// 48-hour window never becomes stale inside the cache period.
var conditionFeedCache = struct {
	sync.Mutex
	refreshed    time.Time
	observations map[string][]cachedConditionObservation
}{observations: make(map[string][]cachedConditionObservation)}

// Parsed match CSV is cached by modification time. Regenerating the CSV updates
// matches without restarting Go, and avoids rereading thousands of rows each hit.
var conditionMatchCache = struct {
	sync.Mutex
	modTime     time.Time
	size        int64
	byWaterbody map[string]map[string]conditionStation
}{}

func WaterbodyConditions(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimSpace(r.PathValue("id"))
	if id == "" {
		writeJSONError(w, http.StatusBadRequest, fmt.Errorf("waterbody ID is required"))
		return
	}
	candidates, err := loadConditionStations(conditionMatchesPath, id)
	if err != nil {
		writeJSONError(w, http.StatusInternalServerError, fmt.Errorf("station matching data: %w", err))
		return
	}
	now := time.Now().UTC()
	result := conditionsResult{
		WaterbodyID: id, AsOf: now, WindowHours: 48,
		Stations: []conditionStation{}, Readings: []conditionReading{}, HistoricalReadings: []conditionReading{},
		Note: "Latest USGS observations at individual stations; not a river-wide average or a safety assessment. Geographical station associations are automated candidates.",
	}
	// A valid waterbody with no strong matches returns empty rather than fetching.
	if len(candidates) == 0 {
		writeJSON(w, http.StatusOK, result)
		return
	}
	observations, err := getCachedConditionFeed(r)
	if err != nil {
		writeJSONError(w, http.StatusBadGateway, fmt.Errorf("USGS conditions: %w", err))
		return
	}
	cutoff := now.Add(-conditionWindow)
	for stationID, station := range candidates {
		for _, observation := range observations[stationID] {
			if observation.Time.After(now.Add(5 * time.Minute)) {
				continue
			}
			reading := conditionReading{
				StationID: stationID, StationName: station.Name,
				ParameterCode: observation.ParameterCode,
				Parameter:     conditionParameters[observation.ParameterCode],
				Value:         observation.Value, Unit: observation.Unit,
				Time: observation.Time, ApprovalStatus: observation.ApprovalStatus,
				SeriesID:  observation.SeriesID,
				Longitude: station.Longitude, Latitude: station.Latitude,
			}
			if observation.Time.Before(cutoff) {
				result.HistoricalReadings = append(result.HistoricalReadings, reading)
			} else {
				result.Readings = append(result.Readings, reading)
			}
		}
	}
	// Historical values are supplementary, not mixed into recent conditions.
	// Restrict payload size: most recent 24 records from up to 8 stations.
	sort.Slice(result.HistoricalReadings, func(i, j int) bool {
		return result.HistoricalReadings[i].Time.After(result.HistoricalReadings[j].Time)
	})
	seenHistoricStations := make(map[string]bool)
	history := make([]conditionReading, 0, 24)
	for _, reading := range result.HistoricalReadings {
		if !seenHistoricStations[reading.StationID] && len(seenHistoricStations) >= 8 {
			continue
		}
		seenHistoricStations[reading.StationID] = true
		history = append(history, reading)
		if len(history) >= 24 {
			break
		}
	}
	result.HistoricalReadings = history
	result.HistoricalStationCount = len(seenHistoricStations)

	active := make(map[string]conditionStation)
	for _, reading := range result.Readings {
		active[reading.StationID] = candidates[reading.StationID]
	}
	for _, station := range active {
		result.Stations = append(result.Stations, station)
	}
	sortConditionResults(&result)
	result.StationCount = len(result.Stations)
	result.ReadingCount = len(result.Readings)
	writeJSON(w, http.StatusOK, result)
}

func loadConditionStations(path, waterbodyID string) (map[string]conditionStation, error) {
	conditionMatchCache.Lock()
	defer conditionMatchCache.Unlock()
	info, err := os.Stat(filepath.Clean(path))
	if err != nil {
		return nil, err
	}
	if conditionMatchCache.byWaterbody == nil || !info.ModTime().Equal(conditionMatchCache.modTime) || info.Size() != conditionMatchCache.size {
		f, err := os.Open(filepath.Clean(path))
		if err != nil {
			return nil, err
		}
		defer f.Close()
		reader := csv.NewReader(f)
		header, err := reader.Read()
		if err != nil {
			return nil, err
		}
		fields := make(map[string]int)
		for i, name := range header {
			fields[strings.TrimPrefix(strings.TrimSpace(name), "\ufeff")] = i
		}
		for _, name := range []string{"waterbody_id", "status", "station_id", "station_name", "longitude", "latitude", "dec_segment_id"} {
			if _, ok := fields[name]; !ok {
				return nil, fmt.Errorf("CSV missing column %q", name)
			}
		}
		all := make(map[string]map[string]conditionStation)
		for {
			record, err := reader.Read()
			if errors.Is(err, io.EOF) {
				break
			}
			if err != nil {
				return nil, err
			}
			get := func(key string) string { return strings.TrimSpace(record[fields[key]]) }
			if get("status") != "STRONG_CANDIDATE" {
				continue
			}
			lon, err1 := strconv.ParseFloat(get("longitude"), 64)
			lat, err2 := strconv.ParseFloat(get("latitude"), 64)
			if err1 != nil || err2 != nil {
				continue
			}
			id, stationID := get("waterbody_id"), get("station_id")
			if id == "" || stationID == "" {
				continue
			}
			if all[id] == nil {
				all[id] = make(map[string]conditionStation)
			}
			all[id][stationID] = conditionStation{ID: stationID, Name: get("station_name"), Longitude: lon, Latitude: lat, SegmentID: get("dec_segment_id")}
		}
		conditionMatchCache.byWaterbody = all
		conditionMatchCache.modTime = info.ModTime()
		conditionMatchCache.size = info.Size()
	}
	stations := conditionMatchCache.byWaterbody[waterbodyID]
	if stations == nil {
		return map[string]conditionStation{}, nil
	}
	return stations, nil // Immutable after publishing cache; no writers mutate these maps.
}

func getCachedConditionFeed(r *http.Request) (map[string][]cachedConditionObservation, error) {
	conditionFeedCache.Lock()
	defer conditionFeedCache.Unlock()
	if !conditionFeedCache.refreshed.IsZero() && time.Since(conditionFeedCache.refreshed) < conditionFeedTTL {
		return conditionFeedCache.observations, nil
	}
	observations, err := fetchStatewideConditionFeed(r)
	if err != nil {
		return nil, err
	}
	conditionFeedCache.observations = observations
	conditionFeedCache.refreshed = time.Now()
	return observations, nil
}

func fetchStatewideConditionFeed(r *http.Request) (map[string][]cachedConditionObservation, error) {
	params := url.Values{}
	params.Set("bbox", nyBoundingBox.String())
	params.Set("f", "json")
	params.Set("limit", "10000")
	params.Set("skipGeometry", "true")
	next := UsgsBaseURL + "/collections/latest-continuous/items?" + params.Encode()
	now := time.Now().UTC()
	// Keep the newest observation per station, parameter and identifiable series.
	// Do not discard old observations: they support a separate historical view.
	best := make(map[string]cachedConditionObservation)
	for page := 0; next != ""; page++ {
		if page >= 500 {
			return nil, fmt.Errorf("USGS pagination exceeded 500 pages")
		}
		parsed, err := url.Parse(next)
		if err != nil || parsed.Scheme != "https" || parsed.Host != "api.waterdata.usgs.gov" {
			return nil, fmt.Errorf("unexpected USGS pagination URL")
		}
		req, err := http.NewRequestWithContext(r.Context(), http.MethodGet, next, nil)
		if err != nil {
			return nil, err
		}
		req.Header.Set("X-Api-Key", cfg.APIKey)
		req.Header.Set("Accept", "application/json")
		resp, err := httpClient.Do(req)
		if err != nil {
			return nil, err
		}
		if resp.StatusCode != http.StatusOK {
			body, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
			resp.Body.Close()
			return nil, fmt.Errorf("USGS %s: %s", resp.Status, string(body))
		}
		var payload struct {
			Features []struct {
				Properties struct {
					MonitoringLocationID string          `json:"monitoring_location_id"`
					ParameterCode        string          `json:"parameter_code"`
					Value                json.RawMessage `json:"value"`
					Unit                 string          `json:"unit_of_measure"`
					Time                 string          `json:"time"`
					ApprovalStatus       string          `json:"approval_status"`
					TimeSeriesID         json.RawMessage `json:"time_series_id"`
					SeriesID             json.RawMessage `json:"series_id"`
				} `json:"properties"`
			} `json:"features"`
			Links []struct {
				Rel  string `json:"rel"`
				Href string `json:"href"`
			} `json:"links"`
		}
		err = json.NewDecoder(io.LimitReader(resp.Body, 32<<20)).Decode(&payload)
		resp.Body.Close()
		if err != nil {
			return nil, fmt.Errorf("decode USGS page %d: %w", page, err)
		}
		for _, feature := range payload.Features {
			p := feature.Properties
			if p.MonitoringLocationID == "" {
				continue
			}
			if _, ok := conditionParameters[p.ParameterCode]; !ok {
				continue
			}
			at := parseUSGSTime(p.Time)
			if at.IsZero() || at.After(now.Add(5*time.Minute)) {
				continue
			}
			number, err := parseConditionNumber(p.Value)
			if err != nil {
				continue
			}
			series := strings.Trim(string(p.TimeSeriesID), `"`)
			if series == "" || series == "null" {
				series = strings.Trim(string(p.SeriesID), `"`)
			}
			if series == "null" {
				series = ""
			}
			observation := cachedConditionObservation{StationID: p.MonitoringLocationID, ParameterCode: p.ParameterCode, Value: number, Unit: p.Unit, Time: at, ApprovalStatus: p.ApprovalStatus, SeriesID: series}
			key := p.MonitoringLocationID + "|" + p.ParameterCode + "|" + series + "|" + at.Format(time.RFC3339Nano) + "|" + strconv.FormatFloat(number, 'g', -1, 64)
			if old, exists := best[key]; !exists || at.After(old.Time) {
				best[key] = observation
			}
		}
		next = ""
		for _, link := range payload.Links {
			if link.Rel == "next" {
				next = link.Href
				break
			}
		}
	}
	result := make(map[string][]cachedConditionObservation)
	for _, observation := range best {
		result[observation.StationID] = append(result[observation.StationID], observation)
	}
	return result, nil
}

func parseConditionNumber(raw json.RawMessage) (float64, error) {
	value := strings.TrimSpace(string(raw))
	if value == "" || value == "null" || value == `""` {
		return 0, fmt.Errorf("empty reading")
	}
	value = strings.Trim(value, `"`)
	number, err := strconv.ParseFloat(value, 64)
	if err != nil {
		return 0, err
	}
	if number != number || number > 1e308 || number < -1e308 {
		return 0, fmt.Errorf("nonfinite reading")
	}
	return number, nil
}

func sortConditionResults(result *conditionsResult) {
	sort.Slice(result.Stations, func(i, j int) bool { return result.Stations[i].ID < result.Stations[j].ID })
	sort.Slice(result.Readings, func(i, j int) bool {
		a, b := result.Readings[i], result.Readings[j]
		if a.StationID != b.StationID {
			return a.StationID < b.StationID
		}
		return a.ParameterCode < b.ParameterCode
	})
}
